using Security;

namespace Plugin.Maui.NearbyConnectivity.DeviceTests.Native;

/// <summary>
/// The ephemeral RSA identity the iOS session hands to <c>MCSession</c>, against the real keychain.
/// </summary>
/// <remarks>
/// None of this can be checked off-device: the key is generated by Security.framework and the
/// identity is formed by <c>SecIdentityCreate</c>, and the key type is not a preference but a hard constraint — a P-256
/// identity makes Multipeer's DTLS handshake fail with <c>SSLHandshake</c> (-9834) and the session
/// never connects, with nothing in the managed layer to catch it.
/// </remarks>
public sealed class EphemeralIdentityTests : DeviceTest
{
    [Fact]
    public void Create_ReturnsAUsableIdentity()
    {
        // Act
        var identity = EphemeralIdentity.Create();

        // Assert
        Assert.NotNull(identity);
        Assert.NotNull(identity.Certificate);
    }

    [Fact]
    public void Create_MintsADistinctIdentityEachTime()
    {
        // Arrange & Act
        var first = EphemeralIdentity.Fingerprint(EphemeralIdentity.Create().Certificate);
        var second = EphemeralIdentity.Fingerprint(EphemeralIdentity.Create().Certificate);

        // Assert
        Assert.NotEqual(first, second);
    }

    [Fact]
    public void Fingerprint_IsSha256OfTheCertificate()
    {
        // Arrange
        var identity = EphemeralIdentity.Create();

        // Act
        var fingerprint = EphemeralIdentity.Fingerprint(identity.Certificate);

        // Assert
        Assert.Equal(32, fingerprint.Length);
    }

    [Fact]
    public void Fingerprint_IsStableForOneCertificate()
    {
        // Arrange
        var identity = EphemeralIdentity.Create();

        // Act
        var first = EphemeralIdentity.Fingerprint(identity.Certificate);
        var second = EphemeralIdentity.Fingerprint(identity.Certificate);

        // Assert
        Assert.Equal(first, second);
    }

    [Fact]
    public void Identity_CanBackAnMCSession()
    {
        // Arrange
        var identity = EphemeralIdentity.Create();
        using var peer = new MCPeerID("identity-test");

        // Act
        using var session = new MCSession(peer, identity, MCEncryptionPreference.Required);

        // Assert
        Assert.NotNull(session);
    }

    // Multipeer abandons a connection whose post-handshake setup outlasts its own ICE timeout,
    // about 12 seconds, and a hosted simulator's trustd has spent 7 of those on one certificate.
    // A lost race is retried; an identity the DTLS handshake rejects fails every attempt.
    [Fact]
    public async Task TwoIdentities_CompleteADtlsHandshake()
    {
        // Act
        var connected = false;
        for (var attempt = 0; attempt < 3 && !connected; attempt++)
        {
            connected = await ConnectTwoSessionsAsync();
        }

        // Assert
        Assert.True(connected);
    }

    static async Task<bool> ConnectTwoSessionsAsync()
    {
        using var aliceId = new MCPeerID("alice");
        using var bobId = new MCPeerID("bob");
        using var alice = new MCSession(aliceId, EphemeralIdentity.Create(), MCEncryptionPreference.Required);
        using var bob = new MCSession(bobId, EphemeralIdentity.Create(), MCEncryptionPreference.Required);
        var aliceWatch = new ConnectionWatch();
        var bobWatch = new ConnectionWatch();
        alice.Delegate = aliceWatch;
        bob.Delegate = bobWatch;

        var aliceSawBob = new TaskCompletionSource<NSData>(TaskCreationOptions.RunContinuationsAsynchronously);
        var bobSawAlice = new TaskCompletionSource<NSData>(TaskCreationOptions.RunContinuationsAsynchronously);
        alice.NearbyConnectionDataForPeer(bobId, (data, error) => Settle(aliceSawBob, data, error));
        bob.NearbyConnectionDataForPeer(aliceId, (data, error) => Settle(bobSawAlice, data, error));

        alice.ConnectPeer(bobId, await bobSawAlice.Task.WaitAsync(TimeSpan.FromSeconds(10), TestContext.Current.CancellationToken));
        bob.ConnectPeer(aliceId, await aliceSawBob.Task.WaitAsync(TimeSpan.FromSeconds(10), TestContext.Current.CancellationToken));

        var connected = await aliceWatch.Settled.Task.WaitAsync(TimeSpan.FromSeconds(30), TestContext.Current.CancellationToken)
            && await bobWatch.Settled.Task.WaitAsync(TimeSpan.FromSeconds(30), TestContext.Current.CancellationToken);

        alice.Disconnect();
        bob.Disconnect();

        if (connected)
        {
            Assert.True(aliceWatch.CertificateReceived);
            Assert.True(bobWatch.CertificateReceived);
        }

        return connected;
    }

    static void Settle(TaskCompletionSource<NSData> tcs, NSData? data, NSError? error)
    {
        if (data is not null)
        {
            tcs.TrySetResult(data);
        }
        else
        {
            tcs.TrySetException(new InvalidOperationException(error?.LocalizedDescription ?? "No connection data."));
        }
    }

    sealed class ConnectionWatch : MCSessionDelegate
    {
        /// <summary>True once connected; false if the attempt fell back to not connected.</summary>
        public TaskCompletionSource<bool> Settled { get; } = new(TaskCreationOptions.RunContinuationsAsynchronously);

        public bool CertificateReceived { get; private set; }

        public override bool DidReceiveCertificate(
            MCSession session,
            SecCertificate[]? certificate,
            MCPeerID peerID,
            Action<bool> certificateHandler)
        {
            CertificateReceived = certificate is { Length: > 0 };
            certificateHandler(true);
            return true;
        }

        public override void DidChangeState(MCSession session, MCPeerID peerID, MCSessionState state)
        {
            if (state is MCSessionState.Connected or MCSessionState.NotConnected)
            {
                Settled.TrySetResult(state is MCSessionState.Connected);
            }
        }

        public override void DidReceiveData(MCSession session, NSData data, MCPeerID peerID)
        {
        }

        public override void DidStartReceivingResource(MCSession session, string resourceName, MCPeerID fromPeer, NSProgress progress)
        {
        }

        public override void DidFinishReceivingResource(MCSession session, string resourceName, MCPeerID fromPeer, NSUrl? localUrl, NSError? error)
        {
        }

        public override void DidReceiveStream(MCSession session, NSInputStream stream, string streamName, MCPeerID peerID)
        {
        }
    }
}
